1	/**
2	 * Link Widget
3	 *
4	 * Renders Markdown link preview, supports standard links and Wiki links
5	 */
6	
7	import { WidgetType } from '@codemirror/view';
8	
9	/**
10	 * Link data interface
11	 */
12	export interface LinkData {
13	  /** Link text */
14	  text: string;
15	  /** Link URL */
16	  url: string;
17	  /** Title */
18	  title?: string;
19	  /** Whether it's a Wiki link */
20	  isWikiLink: boolean;
21	}
22	
23	/**
24	 * Link options interface
25	 */
26	export interface LinkOptions {
27	  /** Whether to open in new tab, default true */
28	  openInNewTab?: boolean;
29	  /** Wiki link click handler */
30	  onWikiLinkClick?: (link: string) => void;
31	  /** Whether to show link preview, default false */
32	  showPreview?: boolean;
33	}
34	
35	/**
36	 * Dangerous protocols list
37	 */
38	const DANGEROUS_PROTOCOLS = ['javascript:', 'vbscript:', 'data:text/html'];
39	
40	/**
41	 * Check if URL is safe
42	 */
43	function isSafeUrl(url: string): boolean {
44	  const lowerUrl = url.toLowerCase().trim();
45	  return !DANGEROUS_PROTOCOLS.some((protocol) => lowerUrl.startsWith(protocol));
46	}
47	
48	/**
49	 * Sanitize URL
50	 */
51	function sanitizeUrl(url: string): string {
52	  if (!isSafeUrl(url)) {
53	    return '';
54	  }
55	  // Encode special characters
56	  try {
57	    return encodeURI(url);
58	  } catch {
59	    return '';
60	  }
61	}
62	
63	/**
64	 * Link Widget class
65	 */
66	export class LinkWidget extends WidgetType {
67	  constructor(
68	    readonly data: LinkData,
69	    readonly options: LinkOptions
70	  ) {
71	    super();
72	  }
73	
74	  /**
75	   * Check if two widgets are equal
76	   */
77	  eq(other: LinkWidget): boolean {
78	    return (
79	      other.data.text === this.data.text &&
80	      other.data.url === this.data.url &&
